WITH lines AS (SELECT id, plan, tier_value FROM price_tiers LATERAL VIEW OUTER EXPLODE(discounts) li AS tier_value), cleaned AS (SELECT *, CASE WHEN tier_value >= 68 THEN 'High' WHEN tier_value >= 34 THEN 'Medium' ELSE 'Low' END AS tier_value_level, CASE WHEN tier_value >= 78 THEN 'High' WHEN tier_value >= 40 THEN 'Medium' ELSE 'Low' END AS tier_value_tier FROM lines WHERE plan = 'starter'), filtered AS (SELECT *, CASE WHEN tier_value >= 64 THEN 'High' WHEN tier_value >= 29 THEN 'Medium' ELSE 'Low' END AS tier_value_level_2 FROM cleaned WHERE plan IN ('basic', 'pro')), base AS (SELECT *, CASE WHEN plan = 'enterprise' THEN 1 ELSE 0 END AS is_enterprise FROM filtered WHERE plan IN ('starter', 'enterprise', 'basic')), with_windows AS (SELECT tier_value, tier_value_level, RANK() OVER (PARTITION BY plan ORDER BY tier_value NULLS FIRST) AS tier_value_rank FROM base), valid AS (SELECT *, tier_value * tier_value_rank AS tier_value_times_tier_value_rank FROM with_windows WHERE tier_value > 45), enriched AS (SELECT tier_value_rank, tier_value_times_tier_value_rank, CUME_DIST() OVER (ORDER BY tier_value DESC) AS tier_value_cume_dist, DENSE_RANK() OVER (ORDER BY tier_value_rank NULLS LAST) AS tier_value_rank_dense_rank, CUME_DIST() OVER (ORDER BY tier_value_times_tier_value_rank DESC) AS tier_value_times_tier_value_rank_cume_dist, DENSE_RANK() OVER (ORDER BY tier_value_rank) AS tier_value_rank_dense_rank_2 FROM valid WHERE tier_value BETWEEN 56 AND 62) SELECT tier_value_times_tier_value_rank, tier_value_cume_dist, tier_value_rank_dense_rank, tier_value_times_tier_value_rank_cume_dist FROM enriched ORDER BY tier_value_cume_dist DESC NULLS LAST;
